/**
 * modules/CoreModule/xiaocheng.js —— 小成图（霍斐然《周易小成图简述》）内核【单一真源 · 适配层】
 *
 * 算什么：一个「本卦之之卦」（或报 4 个数）→ 装进洛书九宫地盘 → 出完整「小成图」：
 *   四正宫（本/之上下卦）/ 四隅宫（本/之互卦）/ 中宫（归藏异或）/ 取用神宫 / 应期 / 阴阳得配。
 *   只做**象数层**结构定位（起图 + 用神 + 应期 + 阴阳得配），不擅自硬下五行吉凶断语。
 *
 * 算法来源（有权威用权威，多源交叉；霍斐然《周易小成图简述》原文 + 易德轩/卦无忧/天海易学/新浪/术数纵横转述）：
 *   · 天地数起卦（霍老《简述》+ 卦无忧 + 天海易学 3 源一致）：
 *       一二三四五六七八九十 → 乾坤艮兑坎离震巽乾坤（奇数阳卦、偶数阴卦，乾坤重出「天地至大而万物生于中」）。
 *       报 4 数：前 2 位组本卦（第 1 位上卦、第 2 位下卦），后 2 位组之卦（第 3 位上卦、第 4 位下卦）。
 *       外部算例（锁死）：1136 → 乾为天 之 山火贲；5596 → 坎为水 之 天火同人。
 *   · 九宫地盘（后天八卦配洛书九宫，永恒不动）：1坎 2坤 3震 4巽 5中 6乾 7兑 8艮 9离。
 *       「地盘为主，先理解地盘」——取用神即取地盘宫的类象与应期。
 *   · 装图（霍老《简述》原文：「履上互排四宫、下互排二宫；晋上互排八宫、下互排六宫」）：
 *       四正宫：本上→9离、本下→1坎、之上→3震、之下→7兑；
 *       四隅宫（互卦）：本上互→4巽、本下互→2坤、之上互→8艮、之下互→6乾。
 *       ⚠ 易德轩/博档版把本互「上→2、下→4」与霍老原文相反 → 属转载异说，本内核以霍老原文为准（见缺口①）。
 *   · 互卦（《周易》通用）：本卦 2·3·4 爻为下互、3·4·5 爻为上互；之卦同理。
 *   · 中宫归藏（「同阴异阳」= 逐位异或；霍老《简述》「四正归藏」：本上⊕本下⊕之上⊕之下）：
 *       异或满足结合律，故「四正连归藏」与简化版「(本归藏)⊕(之归藏)」结果相同。
 *       外部算例（自洽锁死）：1136 中宫=震、5596 中宫=离。
 *       ⚠ 个别转载（卦无忧）把 1136 中宫标题误写「巽」、正文异或推演却得「震」——本内核以异或自洽「震」为准（见缺口②）。
 *   · 取用神 + 应期（霍老《简述》「八卦定吉凶法」+ 头条/卦无忧宫位表，多源一致）：
 *       乾宫主事业功名·九十月 / 坤宫主考学主名风水吉凶·六七月 / 艮宫主门户房屋子息·腊月正月 /
 *       兑宫主口舌饮食桃花喜事·八月 / 坎宫主命病盗失·十一月 / 离宫主性事文书消息·五月 /
 *       震宫主动静迁移官非行人·未婚女问婚姻·二月 / 巽宫主进退财帛·未婚男看婚姻·三四月。
 *   · 阴阳得配（头条「阖辟往来」层的**结构定位**，不展开吉凶四势）：
 *       八卦阴阳：乾震坎艮为阳、坤巽离兑为阴；例外「唯坎主降、独离主升」。
 *       本内核只给「用神宫本位卦 × 落卦」的阴阳属性 + 是否得配（异为得配、同为失配），
 *       完整的「阖/辟/往/来」四势吉凶断语**不硬下**（见缺口③）。
 *
 * 复用（不复制）：八卦三爻/五行/名 = ICE.BAGUA；互卦 = 由 6 爻自算（iching.huGua 口径一致）；64 卦名 = ICE。
 *   iching.BAGUA 是「先天方位」，小成图地盘是「后天九宫」，二者不通用 → 地盘宫位表本文件自带。
 *
 * 加载：UMD —— 小程序 require（注入 ICE=iching）；浏览器挂 NT.core.xiaocheng。
 * 校验：modules/CoreModule/__tests__/xiaocheng.test.js（外部算例 1136/5596 装图逐宫 + 归藏自洽 + 用神应期 + 结构断言）。
 *
 * 交叉验证状态（守零臆造，如实标注，不假报已锁）：
 *   ✅ 确定性部分已锁死：天地数起卦表（3 源一致 + 两个外部算例 1136/5596 逐宫核对）、
 *      九宫地盘（后天八卦通用标准）、装图四正/四隅（霍老原文）、互卦（《周易》通用）、
 *      中宫归藏异或（「同阴异阳」+ 结合律自洽 + 算例 1136→震、5596→离）、用神/应期宫位表（多源一致）。
 *   📌 流派分歧 / 未锁（如实标注）：
 *      ① 四隅互卦装图方位：霍老原文（本上互4/本下互2）与易德轩版（本上互2/本下互4）相反，本内核采霍老原文。
 *      ② 个别转载「中宫」标题与正文异或推演矛盾，本内核以异或自洽为准。
 *      ③ 「阖辟往来」四势（阖/辟/往/来）的**吉凶断语** + 五行生克吉凶：霍老原论「只用象数、不涉五行」，
 *         转述版又引入五行生克/阖辟吉凶且相互冲突（单源、经验性强）→ 本内核只做**结构定位**（阴阳得配），
 *         不硬下「吉/凶/悔/吝」断语；五行生克亦未纳入（小成图原论本不涉五行）。
 */
(function (root, factory) {
  if (typeof module === 'object' && module.exports) {
    module.exports = factory(require('./iching.js'));
  } else {
    root.NT = root.NT || {}; root.NT.core = root.NT.core || {};
    root.NT.core.xiaocheng = factory(root.NT.core && root.NT.core.iching);
  }
})(typeof self !== 'undefined' ? self : this, function (ICE) {

  function 缺() { return { err: '小成图需 iching 内核' }; }

  // ===== 天地数起卦表（霍老《简述》+ 卦无忧 + 天海易学 3 源一致）=====
  // 一~十 = 乾坤艮兑坎离震巽乾坤（奇数阳卦、偶数阴卦；乾坤重出）
  var TIANDI = { 1: '乾', 2: '坤', 3: '艮', 4: '兑', 5: '坎', 6: '离', 7: '震', 8: '巽', 9: '乾', 10: '坤' };
  // 后天九宫地盘（洛书·永恒不动）：宫号 → 宫本位卦名；中五宫无卦
  var DI_GONG = { 1: '坎', 2: '坤', 3: '震', 4: '巽', 6: '乾', 7: '兑', 8: '艮', 9: '离' };
  // 取用神宫位 + 应期（霍老《简述》八卦定吉凶法 + 头条/卦无忧宫位表，多源一致）
  var YONG_SHEN = {
    乾: { 事: '事业功名', 期: '九、十月' },
    坤: { 事: '考学主名·风水吉凶', 期: '六、七月' },
    艮: { 事: '门户房屋·子息', 期: '腊月、正月' },
    兑: { 事: '口舌饮食·桃花喜事', 期: '八月' },
    坎: { 事: '命·病·盗·失', 期: '十一月' },
    离: { 事: '性事·文书·消息', 期: '五月' },
    震: { 事: '动静迁移·官非行人·未婚女问婚姻', 期: '二月' },
    巽: { 事: '进退财帛·未婚男看婚姻', 期: '三、四月' }
  };
  // 八卦阴阳（头条：乾震坎艮为阳、坤巽离兑为阴；唯坎主降、独离主升）
  var GUA_YIN = { 乾: '阳', 震: '阳', 坎: '阳', 艮: '阳', 坤: '阴', 巽: '阴', 离: '阴', 兑: '阴' };

  function 名To号(name) {
    for (var n in ICE.BAGUA) if (ICE.BAGUA[n].名 === name) return +n;
    return 0;
  }
  function 号To名(n) { return ICE.BAGUA[n] ? ICE.BAGUA[n].名 : ''; }

  // 由 4 个单卦名 {本上,本下,之上,之下} 得互卦（本/之各）
  // 互卦：本卦 2·3·4 爻为下互、3·4·5 爻为上互（爻从初到上；下卦3爻+上卦3爻）
  function 互卦(上卦, 下卦) {
    var 下 = ICE.BAGUA[名To号(下卦)].爻, 上 = ICE.BAGUA[名To号(上卦)].爻;
    var yao = 下.concat(上);          // [初,二,三(下卦末),四,五,上]
    var 下互 = [yao[1], yao[2], yao[3]];
    var 上互 = [yao[2], yao[3], yao[4]];
    function 爻To名(t) { for (var n in ICE.BAGUA) if (ICE.BAGUA[n].爻.join('') === t.join('')) return ICE.BAGUA[n].名; return ''; }
    return { 上互: 爻To名(上互), 下互: 爻To名(下互) };
  }

  // 归藏（「同阴异阳」= 逐位异或）：两单卦名 → 一单卦名
  function guiCang(a, b) {
    var A = ICE.BAGUA[名To号(a)].爻, B = ICE.BAGUA[名To号(b)].爻;
    var r = [A[0] ^ B[0], A[1] ^ B[1], A[2] ^ B[2]];
    for (var n in ICE.BAGUA) if (ICE.BAGUA[n].爻.join('') === r.join('')) return ICE.BAGUA[n].名;
    return '';
  }
  // 四正归藏（霍老《简述》）：本上⊕本下⊕之上⊕之下（异或结合律，等价于 (本归藏)⊕(之归藏)）
  function zhongGong(本上, 本下, 之上, 之下) {
    var a = guiCang(本上, 本下), b = guiCang(之上, 之下);
    return { 本归藏: a, 之归藏: b, 中宫: guiCang(a, b) };
  }

  // ===== 报数起卦（天地数：前 2 位本卦、后 2 位之卦）=====
  function 报数起(nums) {
    nums = (nums || '').toString().split('').map(function (c) { return +c; }).filter(function (x) { return !isNaN(x); });
    if (nums.length < 4) return { err: '小成图报数需 4 个数字（前 2 位本卦、后 2 位之卦），例如「小成图 1136」。' };
    function g(n) { var k = (n % 10 === 0) ? 10 : (n % 10); return TIANDI[k]; }
    return {
      本上: g(nums[0]), 本下: g(nums[1]), 之上: g(nums[2]), 之下: g(nums[3]),
      起法: '报数（天地数 1-10 → 乾坤艮兑坎离震巽乾坤，奇阳偶阴）'
    };
  }

  /**
   * 出一张完整小成图。
   * @param {Object} inp { 数字?: '1136', 本上?, 本下?, 之上?, 之下?, 问?: '财|官|病|行|婚…' }
   *   给「数字」走报数起卦；或直接给 4 个单卦名。
   * @returns 完整小成图（象数层结构定位）或 { err }
   */
  function 图(inp) {
    inp = inp || {};
    if (!ICE || !ICE.BAGUA) return 缺();

    var g;
    if (inp.数字 != null && String(inp.数字).length >= 4) g = 报数起(inp.数字);
    else if (inp.本上 && inp.本下 && inp.之上 && inp.之下) g = { 本上: inp.本上, 本下: inp.本下, 之上: inp.之上, 之下: inp.之下, 起法: '直接给单卦' };
    else return { err: '小成图要 4 个数（报数起卦，如「小成图 1136」）或给「本卦上下 + 之卦上下」四个单卦。' };
    if (g.err) return g;

    var 本上 = g.本上, 本下 = g.本下, 之上 = g.之上, 之下 = g.之下;
    // 互卦（本/之各）
    var 本互 = 互卦(本上, 本下), 之互 = 互卦(之上, 之下);
    // 中宫归藏
    var zg = zhongGong(本上, 本下, 之上, 之下);

    // 装图（霍老原文：四正 9/1/3/7、四隅 4/2/8/6）
    var 天盘 = {
      9: 本上, 1: 本下, 3: 之上, 7: 之下,          // 四正
      4: 本互.上互, 2: 本互.下互, 8: 之互.上互, 6: 之互.下互,  // 四隅（互卦，霍老原文方位）
      5: zg.中宫                                     // 中宫归藏
    };

    // 本卦/之卦名（用 ICE 拼 64 名）
    var 本名 = ICE.hexName ? ICE.hexName(号To名(名To号(本上)), 号To名(名To号(本下))) : '';
    var 之名 = ICE.hexName ? ICE.hexName(号To名(名To号(之上)), 号To名(名To号(之下))) : '';

    // 取用神（依「问」取对应宫位；未指定则列全八宫）
    var 问事 = String(inp.问 || '').replace(/[（(].*$/g, '');
    var 用神;
    if (问事) {
      var hits = [];
      var 加 = function (gn) { if (hits.indexOf(gn) < 0) hits.push(gn); };
      if (问事.indexOf('财') >= 0) 加('巽');
      if (问事.indexOf('官') >= 0) 加('乾');
      if (问事.indexOf('名') >= 0) 加('坤');
      if (问事.indexOf('病') >= 0 || 问事.indexOf('失') >= 0 || 问事.indexOf('盗') >= 0) 加('坎');
      if (问事.indexOf('婚') >= 0) { 加('巽'); 加('震'); }   // 未婚男看婚姻→巽、未婚女→震
      if (问事.indexOf('行') >= 0) 加('震');
      if (hits.length === 0) for (var gn0 in YONG_SHEN) hits.push(gn0);   // 无关键词 → 全八宫
      用神 = hits;
    } else 用神 = null;

    // 用神宫的落卦 + 阴阳得配（结构定位，不硬下吉凶）
    function 配(gn) {
      var 宫号 = 0; for (var p in DI_GONG) if (DI_GONG[p] === gn) 宫号 = +p;   // 卦名 → 宫号
      if (!宫号 || !天盘[宫号]) return null;
      var 宫本 = DI_GONG[宫号];                 // 地盘宫本位卦
      var 落 = 天盘[宫号];                     // 天盘落卦
      var y1 = GUA_YIN[落], y2 = GUA_YIN[宫本];
      return {
        宫: 宫号 + '(' + gn + ')', 宫本位: 宫本, 落卦: 落,
        落卦阴阳: y1, 宫本阴阳: y2,
        得配: (y1 && y2 && y1 !== y2) ? '得配（阴阳异）' : (y1 && y2 ? '失配（阴阳同）' : '—'),
        事: YONG_SHEN[gn] ? YONG_SHEN[gn].事 : '', 期: YONG_SHEN[gn] ? YONG_SHEN[gn].期 : ''
      };
    }
    var 用神落 = 用神 ? 用神.map(配) : [];

    return {
      起法: g.起法,
      本卦: 本名 || (本上 + '上' + 本下), 之卦: 之名 || (之上 + '上' + 之下),
      四正: { 9: 本上, 1: 本下, 3: 之上, 7: 之下 },
      四隅: { 4: 本互.上互, 2: 本互.下互, 8: 之互.上互, 6: 之互.下互 },
      互卦: { 本上互: 本互.上互, 本下互: 本互.下互, 之上互: 之互.上互, 之下互: 之互.下互 },
      中宫: { 本归藏: zg.本归藏, 之归藏: zg.之归藏, 中宫: zg.中宫 },
      天盘: 天盘,
      地盘: DI_GONG,
      用神宫: 用神, 用神落: 用神落,
      应期表: YONG_SHEN,
      缺口: [
        '① 四隅互卦装图方位：霍老原文（本上互→巽4/本下互→坤2）与易德轩转载版（本上互→2/本下互→4）相反，本内核采霍老原文。',
        '② 中宫个别转载标题与正文异或推演矛盾，本内核以「同阴异阳」异或自洽为准。',
        '③ 「阖辟往来」四势（阖/辟/往/来）的吉凶断语与五行生克：霍老原论「只用象数、不涉五行」，转述版引入五行生克且互斥（单源、经验性强）→ 本内核只做象数结构定位（阴阳得配），不硬下吉/凶/悔/吝断语，五行亦未纳入。'
      ].join('\n')
    };
  }

  return {
    图: 图, 报数起: 报数起, guiCang: guiCang, zhongGong: zhongGong, 互卦: 互卦,
    TIANDI: TIANDI, DI_GONG: DI_GONG, YONG_SHEN: YONG_SHEN, GUA_YIN: GUA_YIN,
    名To号: 名To号
  };
});
